func (this *Nobitex) HandleErrors(httpCode any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if IsEqual(response, nil) {
		return nil
	}
	//
	//     { "status": "failed", "code": "InvalidSymbol", "message": "..." }
	//     { "detail": "توکن غیر مجاز" } // invalid token, http 401
	//
	if (IsEqual(httpCode, 401)) || (IsEqual(httpCode, 403)) {
		panic(AuthenticationError(Add(Add(this.Id, " "), body)))
	}
	var status *string = this.SafeString(response, "status")
	if (status != nil) && (status == nil || *status != "ok") {
		panic(ExchangeError(Add(Add(this.Id, " "), body)))
	}
	return nil
}

